package com.bank.chat;

import java.util.*;
import java.util.logging.*;

public class ChatDemo {
    private static final Logger log = Logger.getLogger("Chat");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SessionRegistry registry = new SessionRegistry();
        OfflineQueue offline = new OfflineQueue();
        MessageStore store = new MessageStore();
        ChatService chat = new ChatService(registry, offline, store);

        // Rajesh is online; Priya is NOT connected yet
        registry.connect("SAV2001", msg -> log.info(() -> "  Rajesh device shows: " + msg));

        // Rajesh sends two messages to offline Priya → queued
        chat.send("SAV2001", "CUR3001", "Hi Priya, about my loan EMI?");
        chat.send("SAV2001", "CUR3001", "Can we reduce the tenure?");

        // Priya connects → queued messages flush in order, acks flow back
        log.info("Priya connects...");
        registry.connect("CUR3001", msg -> {
            log.info(() -> "  Priya device shows: " + msg);
        });
        chat.onUserConnected("CUR3001");

        // Priya acknowledges delivery then reads
        store.all().forEach(m -> {
            if (m.getTo().equals("CUR3001")) {
                chat.onDelivered(m.getId());
                chat.onRead(m.getId());
            }
        });
    }
}

