package com.bank.chat;

public class ChatMessage {
    public enum Status { SENT, DELIVERED, READ }
    private final String id;
    private final String from;
    private final String to;
    private final String body;      // in production: ciphertext (E2E encrypted)
    private final long seq;         // per-conversation ordering
    private Status status = Status.SENT;

    public ChatMessage(String id, String from, String to, String body, long seq) {
        this.id = id; this.from = from; this.to = to; this.body = body; this.seq = seq;
    }
    public String getId() { return id; }
    public String getFrom() { return from; }
    public String getTo() { return to; }
    public String getBody() { return body; }
    public long getSeq() { return seq; }
    public Status getStatus() { return status; }
    public void markDelivered() { if (status == Status.SENT) status = Status.DELIVERED; }
    public void markRead() { status = Status.READ; }
}
