package com.bank.chat;

import java.util.*;
import java.util.function.Consumer;

// Maps an online user to their live push callback (the WebSocket).
public class SessionRegistry {
    private final Map<String, Consumer<String>> sessions = new HashMap<>();
    public void connect(String userId, Consumer<String> pushCallback) {
        sessions.put(userId, pushCallback);
    }
    public boolean isOnline(String userId) { return sessions.containsKey(userId); }
    public void push(String userId, String msg) {
        Consumer<String> cb = sessions.get(userId);
        if (cb != null) cb.accept(msg);
    }
}
