package com.bank.chat;

import java.util.*;

public class OfflineQueue {
    private final Map<String, Deque<ChatMessage>> queues = new HashMap<>();
    public void enqueue(String userId, ChatMessage m) {
        queues.computeIfAbsent(userId, k -> new ArrayDeque<>()).addLast(m);
    }
    public List<ChatMessage> drain(String userId) {
        Deque<ChatMessage> q = queues.remove(userId);
        return q == null ? List.of() : new ArrayList<>(q);
    }
}
