package com.bank.chat;

import java.util.*;

// Durable history: every message persisted before delivery attempt.
public class MessageStore {
    private final Map<String, ChatMessage> byId = new LinkedHashMap<>();
    public void save(ChatMessage m) { byId.put(m.getId(), m); }
    public ChatMessage find(String id) { return byId.get(id); }
    public Collection<ChatMessage> all() { return byId.values(); }
}
