// ─── File: ChatService.java ───
package com.bank.chat;

import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.*;

public class ChatService {
    private static final Logger log = Logger.getLogger("Chat");
    private final SessionRegistry registry;
    private final OfflineQueue offline;
    private final MessageStore store;
    private final AtomicLong seq = new AtomicLong();

    public ChatService(SessionRegistry registry, OfflineQueue offline, MessageStore store) {
        this.registry = registry; this.offline = offline; this.store = store;
    }

    public void send(String from, String to, String body) {
        ChatMessage m = new ChatMessage(UUID.randomUUID().toString(), from, to, body, seq.incrementAndGet());
        store.save(m);  // persist FIRST (never lose a message)
        log.info(() -> "SENT " + from + "->" + to + " seq=" + m.getSeq());
        if (registry.isOnline(to)) {
            registry.push(to, body);     // online: deliver now
        } else {
            offline.enqueue(to, m);       // offline: queue for later
            log.warning(() -> to + " offline, message queued");
        }
    }

    // called when a user reconnects: flush queued messages in order
    public void onUserConnected(String userId) {
        List<ChatMessage> pending = offline.drain(userId);
        pending.sort(Comparator.comparingLong(ChatMessage::getSeq));
        for (ChatMessage m : pending) {
            registry.push(userId, m.getBody());
            log.info(() -> "flushed queued seq=" + m.getSeq() + " to " + userId);
        }
    }

    public void onDelivered(String messageId) {
        ChatMessage m = store.find(messageId);
        if (m != null) { m.markDelivered(); log.info(() -> "DELIVERED seq=" + m.getSeq()); }
    }

    public void onRead(String messageId) {
        ChatMessage m = store.find(messageId);
        if (m != null) { m.markRead(); log.info(() -> "READ seq=" + m.getSeq()); }
    }
}
